177	    /**
178	     * Updates mutable project fields (`Name` and/or `Description`).
179	     * Always updates `DateModified`. Keeps the index in sync when `Name` changes.
180	     *
181	     * @throws {Error} If no project with the given ID exists.
182	     */
183	    update(id: string, changes: { Name?: string; Description?: string }): ProjectData {
184	        const project = this.loadProject(id);
185	        if (!project) {
186	            throw new NotFoundError(`Cannot update: project with ID "${id}" does not exist.`);
187	        }
188	
189	        if (changes.Name !== undefined) {
190	            project.Name = changes.Name;
191	        }
192	        if (changes.Description !== undefined) {
193	            project.Description = changes.Description;
194	        }
195	        project.DateModified = this.now();
196	        this.saveProject(project);
197	
198	        if (changes.Name !== undefined) {
199	            const index = this.loadIndex();
200	            const entry = index.Projects.find((p) => p.Id === id);
201	            if (entry) {
202	                entry.Name = changes.Name;
203	                this.saveIndex(index);
204	            }
205	        }
206	
207	        return project;
208	    }
